begin;create extension if not exists pgtap with schema extensions;select no_plan();
\ir helpers/signal_recovery_fixtures.sql
select pg_temp.source_setup(n)from generate_series(1,10)n;
select is(pg_temp.source_command(1,'RECONNECT',jsonb_build_object('at',clock_timestamp()))->>'state','CONNECTED','first fake connection; no real session');
select is(private.signal_source_result_v1(pg_temp.signal_case_id(1,'2000'),pg_temp.signal_case_id(1,'3000'))->>'can_dispatch','false','connection without observed activity cannot dispatch');
select is(pg_temp.source_observe(1,1)->>'last_sequence','1','first sequence persisted');
select is(private.signal_fixture_gate((select j from private.signal_deliveries j where tenant_id=pg_temp.signal_case_id(1,'2000'))),null,'new source policy hash matches queued generation');
select is(pg_temp.source_observe(1,1)->>'processed','0','identical event replay does not promote twice');
select is((select count(*)::int from private.signal_events where tenant_id=pg_temp.signal_case_id(1,'2000')),1,'one immutable event');
select is(pg_temp.source_observe(1,3,'third')->>'state','GAP_DETECTED','missing second event explicitly detected');
select is((select count(*)::int from private.signal_events where tenant_id=pg_temp.signal_case_id(1,'2000')),1,'out-of-order event quarantined');
select isnt(private.signal_fixture_gate((select j from private.signal_deliveries j where tenant_id=pg_temp.signal_case_id(1,'2000'))),null,'gap fences old queued work');
select is(pg_temp.source_observe(1,2,'second')->>'processed','2','consecutive arrival drains second and third atomically');
select is((select count(*)::int from private.signal_events where tenant_id=pg_temp.signal_case_id(1,'2000')),3,'no silent event loss');
select is(pg_temp.source_command(1,'DISCONNECT',jsonb_build_object('at',clock_timestamp()))->>'state','DISCONNECTED','short disconnect recorded');
select is(pg_temp.source_command(1,'RECONNECT',jsonb_build_object('at',clock_timestamp()))->>'state','RECOVERING','reconnect does not invent recovered history');
select is(pg_temp.source_observe(1,3,'third')->>'state','RECOVERING','duplicate callback after reconnect cannot prove outage recovered');
select is(pg_temp.source_command(1,'RECOVER',jsonb_build_object('page',pg_temp.source_page(1,4,4,jsonb_build_array(jsonb_build_object('sequence',4,'event',pg_temp.signal_dispatch_input(1,'one',2,'EDIT')::jsonb)))))->>'state','CONNECTED','independent fake history restores continuity');
select is((select revision from private.signal_heads where tenant_id=pg_temp.signal_case_id(1,'2000')and message_key='one'),2,'edit during outage preserved');
select is(pg_temp.source_command(1,'DISCONNECT',jsonb_build_object('at',clock_timestamp()-interval '16 minutes'))->>'state','DISCONNECTED','long outage tracked without sleep');
select is(pg_temp.source_command(1,'RECONNECT',jsonb_build_object('at',clock_timestamp()))->>'state','UNRECOVERABLE','bounded window fails closed');
select is(pg_temp.source_command(1,'RECONNECT',jsonb_build_object('at',clock_timestamp()))->>'state','UNRECOVERABLE','network retry cannot reset terminal obligation');
select is(pg_temp.source_command(2,'RECONNECT',jsonb_build_object('at',clock_timestamp()))->>'state','CONNECTED','independent source connection');
select is(pg_temp.source_observe(2,1,'restricted',1,'RESTRICTED')->>'state','SOURCE_RESTRICTED','restriction is explicit');
select is(pg_temp.source_observe(2,2,'unrestricted')->>'state','SOURCE_RESTRICTED','new content cannot silently lift restriction');
select is((select count(*)::int from private.signal_events where tenant_id=pg_temp.signal_case_id(2,'2000')),0,'protected/unverified contents not dispatched');
select throws_ok($$select private.signal_source_configure_fixture_v1(pg_temp.signal_case_id(2,'2000'),pg_temp.signal_case_id(2,'3000'),pg_temp.source_caps())$$,'42501','SOURCE_CONFIG_IMMUTABLE','alternative source required, no cap-reset bypass');
select is(pg_temp.source_command(3,'RECONNECT',jsonb_build_object('at',clock_timestamp()))->>'financial_authority','NONE','synthetic authority always NONE');
select is(pg_temp.source_command(3,'RECONNECT',jsonb_build_object('at',clock_timestamp()))->>'live_operations_authorized','false','no genuine operation authority');
select pg_temp.source_observe(3,2,'missing-first');
select is(pg_temp.source_command(3,'RECOVER',jsonb_build_object('page',pg_temp.source_page(3,1,2,'[]',false)))->>'state','RECOVERING','incomplete page remains unresolved');
select is((select last_sequence from private.signal_source_runtime where tenant_id=pg_temp.signal_case_id(3,'2000')),0,'incomplete proof cannot advance checkpoint');
select pg_temp.source_command(3,'RECOVER',jsonb_build_object('page',pg_temp.source_page(3,1,2,'[]',false)));
select is(pg_temp.source_command(3,'RECOVER',jsonb_build_object('page',pg_temp.source_page(3,1,2,'[]',false)))->>'state','UNRECOVERABLE','three incomplete recovery attempts require review');
select throws_ok($$select private.signal_source_command_fixture_v1(pg_temp.signal_case_id(3,'2000'),pg_temp.signal_case_id(3,'3000'),1,extensions.gen_random_uuid(),'{}')$$,'40001','SOURCE_CHECKPOINT_FENCED','stale checkpoint rejected');
select throws_ok($$select private.signal_source_command_fixture_v1(pg_temp.signal_case_id(3,'2000'),pg_temp.signal_case_id(4,'3000'),1,extensions.gen_random_uuid(),'{}')$$,'42501','source scope unavailable','wrong tenant/source denied');
select pg_temp.source_command(4,'RECONNECT',jsonb_build_object('at',clock_timestamp()));select pg_temp.source_observe(4,1);
select is(pg_temp.source_observe(4,1,'different-facts')->>'state','CONFLICT','same sequence with conflicting facts freezes source');
select pg_temp.source_setup(11,pg_temp.source_caps('UNSUPPORTED'));
select is(pg_temp.source_command(11,'RECONNECT',jsonb_build_object('at',clock_timestamp()))->>'state','LIMITED','unknown sequence capability cannot prove continuity');
select is(pg_temp.source_observe(11,1)->>'processed','0','unsupported sequence does not invent recovery');
select pg_temp.source_command(5,'RECONNECT',jsonb_build_object('at',clock_timestamp()));
create temp table replay_result as select pg_temp.source_command(5,'OBSERVE',jsonb_build_object('sequence',1,'event',pg_temp.signal_dispatch_input(5)::jsonb),'51d09000-0000-4000-8000-000000000001')v;
select is(pg_temp.source_command(5,'OBSERVE',jsonb_build_object('sequence',1,'event',pg_temp.signal_dispatch_input(5)::jsonb),'51d09000-0000-4000-8000-000000000001')->>'replay','true','unknown-commit recovery is idempotent');
select is((select count(*)::int from private.signal_source_recovery_log where tenant_id=pg_temp.signal_case_id(5,'2000')),2,'duplicate command does not append another outcome');
select throws_ok($$update private.signal_source_observations set original='{}'where tenant_id=pg_temp.signal_case_id(5,'2000')$$,'42501','FSE_IMMUTABLE','original source observations immutable');
select throws_ok($$delete from private.signal_source_recovery_log where tenant_id=pg_temp.signal_case_id(5,'2000')$$,'42501','FSE_IMMUTABLE','recovery audit immutable');
select ok(not has_function_privilege('authenticated','private.signal_source_command_fixture_v1(uuid,uuid,integer,uuid,text)','EXECUTE'),'no browser recovery writer');
select ok(not has_function_privilege('service_role','private.signal_source_command_fixture_v1(uuid,uuid,integer,uuid,text)','EXECUTE'),'no service-role writer');
select ok(not has_table_privilege('authenticated','private.signal_source_observations','SELECT'),'no raw observation exposure');
select pg_temp.source_command(6,'RECONNECT',jsonb_build_object('at',clock_timestamp()));select pg_temp.source_observe(6,1);
select pg_temp.source_command(6,'DISCONNECT',jsonb_build_object('at',clock_timestamp()));select pg_temp.source_command(6,'RECONNECT',jsonb_build_object('at',clock_timestamp()));
select is(pg_temp.source_command(6,'RECOVER',jsonb_build_object('page',pg_temp.source_page(6,2,2,jsonb_build_array(jsonb_build_object('sequence',2,'event',pg_temp.signal_dispatch_input(6,'one',2,'DELETE')::jsonb)))))->>'last_sequence','2','delete observed through independent fake outage history');
select is((select e.kind from private.signal_heads h join private.signal_events e on e.id=h.event_id and e.tenant_id=h.tenant_id where h.tenant_id=pg_temp.signal_case_id(6,'2000') and h.message_key='one'),'DELETE','deletion preserved, no recreated signal');
select pg_temp.source_command(7,'RECONNECT',jsonb_build_object('at',clock_timestamp()));
select is(pg_temp.source_command(7,'RECOVER',jsonb_build_object('page',pg_temp.source_page(7,1,65,'[]')))->>'processed','0','recovery cannot read more than64 entries');
select is(pg_temp.source_command(7,'RECOVER',jsonb_build_object('page',pg_temp.source_page(7,1,1,'[]')||'{"origin":"CALLBACK_CACHE"}'::jsonb))->>'processed','0','callback cache is not independent recovery proof');
select is(pg_temp.source_command(8,'RECOVER',jsonb_build_object('page',pg_temp.source_page(8,1,1,jsonb_build_array(jsonb_build_object('sequence',1,'event',pg_temp.signal_dispatch_input(8)::jsonb)))||'{"from":"1"}'::jsonb))->>'processed','0','string checkpoint cannot impersonate numeric sequence');
select pg_temp.source_command(9,'RECONNECT',jsonb_build_object('at',clock_timestamp()));select pg_temp.source_observe(9,1);
update private.signal_source_runtime set last_activity_at=statement_timestamp()-interval '61 seconds' where tenant_id=pg_temp.signal_case_id(9,'2000');
select is(private.signal_source_result_v1(pg_temp.signal_case_id(9,'2000'),pg_temp.signal_case_id(9,'3000'))->>'can_dispatch','false','stale connection cannot claim source freshness');
update private.signal_controls set enabled=false where tenant_id=pg_temp.signal_case_id(10,'2000');
select is(private.signal_source_result_v1(pg_temp.signal_case_id(10,'2000'),pg_temp.signal_case_id(10,'3000'))->>'can_dispatch','false','disabled fixture cannot present dispatch authority');
select * from finish();rollback;
